query PlansAndRooms($accommodationId: AccommodationIdScalar!, $accommodationAmountInput: AccommodationAmountInput!, $themeAccommodationAmountInput: AccommodationAmountInput!, $hasCheckInDate: Boolean! = false, $onPlans: Boolean! = false, $plansInput: SearchPlansInput! = {}, $plansFirst: Int! = 3, $plansOffset: Int! = 0, $planAmountsInput: PlanAmountInput! = {sortItem: "1", sortOrder: "1"}, $onRooms: Boolean! = false, $roomsInput: SearchRoomsInput! = {}, $roomsFirst: Int! = 3, $roomsOffset: Int! = 0, $roomAmountsInput: RoomAmountInput! = {sortItem: "1", sortOrder: "1"}, $highestPointRoomAmountInput: RoomAmountInput!, $amountsAndPlanFirst: Int! = 1, $amountsAndRoomFirst: Int! = 1, $currency: Currency!, $isInternationalSite: Boolean!) {
  accommodation(accommodationId: $accommodationId) {
    __typename
    accommodationId
    allowInstantDiscount
    ...PlanListAccommodationAllowInstantDiscount
    ...RoomListAccommodationAllowInstantDiscount
    ...AccommodationLowestAmountAccommodation
    ...AccommodationHeroboxAccommodationLowestAmount
    ...AccommodationHeroboxAccommodationDisappearingInventory @include(if: $hasCheckInDate)
    ...AccommodationThemeListAccommodationRecommend
    searchPlans2(input: $plansInput, first: $plansFirst, offset: $plansOffset) {
      facet @include(if: $onPlans) {
        ...AccommodationAvailabilityCalendarSearchPlansFacet
        ...PlanAndRoomFilterSearchPlansFacet
      }
      plans {
        ...PlanListPlanConnectionAccommodation @include(if: $onPlans)
        ...RoomPlanMetaPlanConnection @include(if: $onPlans)
        ...PlanOrRoomChoicePlanConnection
      }
    }
    searchRooms2(input: $roomsInput, first: $roomsFirst, offset: $roomsOffset) {
      facet @include(if: $onRooms) {
        ...AccommodationAvailabilityCalendarSearchRoomsFacet
        ...PlanAndRoomFilterSearchRoomsFacet
      }
      rooms {
        ...AccommodationFaqListRoomConnection @include(if: $onRooms)
        ...RoomListRoomConnectionAccommodation @include(if: $onRooms)
        ...RoomPlanMetaRoomConnection @include(if: $onRooms)
        ...PlanOrRoomChoiceRoomConnection
      }
    }
  }
}

fragment ZenkokuCouponsLabelAccommodation on Accommodation {
  accommodationId
  zenkokuCouponTarget2
  zenkokuCoupons {
    name
    status
    coupons {
      hasUserPrefectureRestriction
      prefecture {
        name
      }
    }
  }
}

fragment PointBurdenBreakdownPointBurdenRates on PointBurdenRates {
  accommodation
  other
}

fragment BaseDiscountDescriptionAmountDetail on AmountDetail {
  baseDiscount {
    baseDiscount {
      rate {
        settings {
          rate
          days
        }
        type
      }
      expirationTo
      promotionEntry {
        id
      }
    }
    appliedRate
  }
  date
}

fragment UwanosePointDetailAmount2 on Amount2 {
  amount
  point
  uwanosePoint
}

fragment AccommodationAmountAmount2 on Amount2 {
  amount
  baseDiscountAmount
  baseDiscountRate
  baseDiscountAmountWithCurrency: baseDiscountAmount(currency: $currency) @include(if: $isInternationalSite)
  childACount
  childBCount
  childCCount
  childDCount
  childECount
  childFCount
  discountAmount
  discountAmountEarn
  discountAmountWithoutCoupon
  discountAmountWithCurrency: discountAmount(currency: $currency) @include(if: $isInternationalSite)
  instantPoint
  instantPointRate
  lodgingCount
  peopleCount
  point
  pointRate
  roomCount
  uwanosePoint
  pointBurdenRates {
    ...PointBurdenBreakdownPointBurdenRates
  }
  zenkokuCoupon {
    displayName
    discountRate
    status
  }
  coupon {
    price
  }
  plan {
    meal {
      code
      name
    }
    sale
  }
  details {
    ...BaseDiscountDescriptionAmountDetail
  }
  ...UwanosePointDetailAmount2
}

fragment AccommodationLowestAmountAccommodation on Accommodation {
  amount2(input: $accommodationAmountInput) {
    ...AccommodationAmountAmount2
    plan {
      planId
      checkInTimeFrom
      checkOutTime
      attributes {
        value
        name
      }
      amenities {
        amenity {
          id
          name
        }
        available
      }
    }
    room {
      roomId
      name
      beds {
        count
        peopleCount
        width
        height
        length
      }
      capacityMax
      attributes {
        value
        name
      }
      isAmenitiesDisplay
      amenities {
        amenity {
          id
          name
        }
        available
      }
      images(first: 50) {
        url
        alt
      }
    }
    pointRate
    instantPointRate
  }
}

fragment ThemeAccommodationPersonalizedThemeFeaturedAccommodation on PersonalizedThemeFeaturedAccommodation {
  accommodation {
    ...ZenkokuCouponsLabelAccommodation
    accommodationId
    name
    areaName
    prefecture {
      code
      name
    }
    rating2 {
      average
    }
    imageUrls
    allowInstantDiscount
    amount2(input: $themeAccommodationAmountInput) {
      peopleCount
      ...AccommodationAmountAmount2
    }
  }
  thumbnailImageUrl
}

