fragment RoomHighlightedPointRoom on Room {
  highestPointAmounts: amounts(input: $highestPointRoomAmountInput, first: 1) {
    edges {
      node {
        point
        pointRate
      }
    }
  }
}

fragment RoomListRoom on Room {
  accommodationId
  roomId
  checkInTimeFrom
  checkInTimeTo
  checkOutTime
  amounts(input: $roomAmountsInput, first: $amountsAndPlanFirst) {
    edges {
      node {
        amount
        baseDiscountAmount
        baseDiscountRate
        discountAmount
        point
        pointRate
        instantPoint
        instantPointRate
        inventory
        lodgingCount
        peopleCount
        childACount
        childBCount
        childCCount
        childDCount
        childECount
        childFCount
        roomCount
        plan {
          planId
          checkInTimeFrom
          checkInTimeTo
          checkOutTime
          useCheckInOut
          limitedTwoWeeks
          bookableStartSoon
          bookableEndSoon
          meal {
            code
            name
          }
          memberRank
          name
          imageUrls(first: 1)
          sale
          uwanosePointVariation
        }
        ...AccommodationAmountAmount2
        ...UwanosePointLabelAmount2
      }
    }
    totalCount
  }
  attributes {
    value
  }
  images(first: 99) {
    alt
    url
  }
  meterFrom
  beds {
    count
    peopleCount
    width
    height
    length
  }
  capacityMin
  capacityMax
  floorPlan
  floorNumberBottom
  floorNumberTop
  name
  renewalDate
  type {
    code
    name
  }
  ...RoomHighlightedPointRoom
}

fragment PlanListAccommodationAllowInstantDiscount on Accommodation {
  allowInstantDiscount
  ...ZenkokuCouponsLabelAccommodation
}

fragment RoomListAccommodationAllowInstantDiscount on Accommodation {
  allowInstantDiscount
  ...ZenkokuCouponsLabelAccommodation
}

fragment AccommodationHeroboxAccommodationLowestAmount on Accommodation {
  ...AccommodationLowestAmountAccommodation
}

fragment AccommodationHeroboxAccommodationDisappearingInventory on Accommodation {
  disappearingInventory(input: $roomsInput)
}

fragment AccommodationThemeListAccommodationRecommend on Accommodation {
  accommodationId
  personalization {
    themes(first: 10, offset: 0) {
      edges {
        node {
          themeId
          name
          urlPath
          accommodations(first: 10, offset: 0) {
            edges {
              node {
                thumbnailImageUrl
                accommodation {
                  accommodationId
                  allowInstantDiscount
                  amount2(input: $themeAccommodationAmountInput) {
                    peopleCount
                  }
                }
                ...ThemeAccommodationPersonalizedThemeFeaturedAccommodation
              }
            }
          }
        }
      }
    }
  }
}

fragment AccommodationAvailabilityCalendarSearchPlansFacet on SearchPlansFacet {
  ...KodawariFilterSearchPlansFacetAccommodation
}

fragment PlanAndRoomFilterSearchPlansFacet on SearchPlansFacet {
  ...KodawariFilterSearchPlansFacetAccommodation
}

fragment PlanListPlanConnectionAccommodation on PlanConnection {
  __typename
  edges @include(if: $onPlans) {
    node {
      planId
      bookableStartSoon
      bookableEndSoon
      limitedTwoWeeks
      memberRank
      uwanosePointVariation
      ...PlanListPlan
    }
  }
  totalCount
}

fragment RoomPlanMetaPlanConnection on PlanConnection {
  edges {
    node {
      planId
      amounts(input: $planAmountsInput, first: $amountsAndRoomFirst) {
        edges {
          node {
            room {
              roomId
              images(first: 1) {
                alt
                url
              }
            }
          }
        }
      }
      imageUrls(first: 1)
    }
  }
}

fragment PlanOrRoomChoicePlanConnection on PlanConnection {
  totalCount
}

fragment AccommodationAvailabilityCalendarSearchRoomsFacet on SearchRoomsFacet {
  ...KodawariFilterSearchRoomsFacetAccommodation
}

fragment PlanAndRoomFilterSearchRoomsFacet on SearchRoomsFacet {
  ...KodawariFilterSearchRoomsFacetAccommodation
}

fragment AccommodationFaqListRoomConnection on RoomConnection {
  edges {
    node {
      attributes {
        value
      }
    }
  }
}

fragment RoomListRoomConnectionAccommodation on RoomConnection {
  __typename
  edges @include(if: $onRooms) {
    node {
      roomId
      accommodationId
      ...RoomListRoom
    }
  }
  totalCount
}

fragment RoomPlanMetaRoomConnection on RoomConnection {
  edges {
    node {
      roomId
      amounts(input: $roomAmountsInput, first: $amountsAndPlanFirst) {
        edges {
          node {
            plan {
              planId
              imageUrls(first: 1)
            }
          }
        }
      }
      images(first: 99) {
        alt
        url
      }
    }
  }
}

fragment PlanOrRoomChoiceRoomConnection on RoomConnection {
  totalCount
}
